// Single definition of what the web server must do for the static export (out/):
// security headers, the home redirect and the 404 page. It feeds both the Apache file
// (scripts/build-htaccess.mjs) and the local test server (scripts/static-server.mjs),
// so the E2E tests exercise the same rules that are deployed.

/** Canonical origin; must equal `site.domain` in src/content/site.ts (checked by a unit test). */
export const SITE_ORIGIN = 'https://archica.pl';

/** `/` and unknown languages go here (301). */
export const HOME_PATH = '/pl/';

/**
 * Files generated by Next.js without an extension (image routes). Servers cannot guess
 * their type, so the type is declared explicitly. Checked against the build output.
 */
export const FORCED_TYPES = {
  'apple-icon': 'image/png',
  'opengraph-image': 'image/png',
};

/**
 * CSP without nonces is a deliberate choice (BLUEPRINT §10): the site has no forms, no user
 * data and no third-party scripts. `unsafe-inline` is needed for the inline scripts Next.js emits.
 * `upgradeInsecure: false` is for the local server only (WebKit upgrades http://localhost).
 */
export function contentSecurityPolicy({ upgradeInsecure = true } = {}) {
  const directives = [
    ['default-src', ["'self'"]],
    ['script-src', ["'self'", "'unsafe-inline'"]],
    ['style-src', ["'self'", "'unsafe-inline'"]],
    ['img-src', ["'self'", 'data:', 'blob:']],
    ['font-src', ["'self'"]],
    ['connect-src', ["'self'"]],
    ['object-src', ["'none'"]],
    ['base-uri', ["'self'"]],
    ['form-action', ["'self'"]],
    ['frame-ancestors', ["'none'"]],
  ];
  const parts = directives.map(([name, values]) => `${name} ${values.join(' ')}`);
  if (upgradeInsecure) parts.push('upgrade-insecure-requests');
  return parts.join('; ');
}

/** Response headers for every file, as [name, value] pairs. `preview` adds X-Robots-Tag: noindex. */
export function securityHeaders(options) {
  const headers = [
    ['Content-Security-Policy', contentSecurityPolicy(options)],
    // No includeSubDomains / preload until it is confirmed that no archica.pl subdomain runs on HTTP.
    ['Strict-Transport-Security', 'max-age=63072000'],
    ['X-Content-Type-Options', 'nosniff'],
    ['Referrer-Policy', 'strict-origin-when-cross-origin'],
    ['Permissions-Policy', 'camera=(), microphone=(), geolocation=(), browsing-topics=()'],
    ['X-Frame-Options', 'DENY'],
    ['Cross-Origin-Opener-Policy', 'same-origin'],
  ];
  if (options?.preview) headers.push(['X-Robots-Tag', 'noindex, nofollow']);
  return headers;
}

/** HTML is revalidated on every visit (hashed assets are cached for a year, see .htaccess). */
export const HTML_CACHE = 'no-cache';
